56	namespace {
57	
58	constexpr auto GET_PEER_INTERVAL = 15_min;
59	// Interval when the size of peer list is low.
60	constexpr auto GET_PEER_INTERVAL_LOW = 5_min;
61	// Interval when the peer list is empty.
62	constexpr auto GET_PEER_INTERVAL_ZERO = 1_min;
63	// Interval for retry.
64	constexpr auto GET_PEER_INTERVAL_RETRY = 5_s;
65	// Maximum retries. Try more than 5 to drop bad node.
66	const int MAX_RETRIES = 10;
67	
68	} // namespace
69	
70	DHTGetPeersCommand::DHTGetPeersCommand(cuid_t cuid, RequestGroup* requestGroup,
71	                                       DownloadEngine* e)
72	    : Command{cuid},
73	      requestGroup_{requestGroup},
74	      e_{e},
75	      taskQueue_{nullptr},
76	      taskFactory_{nullptr},
77	      numRetry_{0},
78	      lastGetPeerTime_{Timer::zero()}
79	{
80	  requestGroup_->increaseNumCommand();
81	}
82	
83	DHTGetPeersCommand::~DHTGetPeersCommand()
84	{
85	  requestGroup_->decreaseNumCommand();
86	}
87	
88	bool DHTGetPeersCommand::execute()
89	{
90	  if (btRuntime_->isHalt()) {
91	    return true;
92	  }
93	  auto elapsed = lastGetPeerTime_.difference(global::wallclock());
94	  if (!task_ && (elapsed >= GET_PEER_INTERVAL ||
95	                 (((btRuntime_->lessThanMinPeers() &&
96	                    ((numRetry_ && elapsed >= GET_PEER_INTERVAL_RETRY) ||
97	                     elapsed >= GET_PEER_INTERVAL_LOW)) ||
98	                   (btRuntime_->getConnections() == 0 &&
99	                    elapsed >= GET_PEER_INTERVAL_ZERO))))) {
100	    A2_LOG_DEBUG(
101	        fmt("Issuing PeerLookup for infoHash=%s",
102	            bittorrent::getInfoHashString(requestGroup_->getDownloadContext())
103	                .c_str()));
104	    task_ = taskFactory_->createPeerLookupTask(
105	        requestGroup_->getDownloadContext(), e_->getBtRegistry()->getTcpPort(),
106	        peerStorage_);
107	    taskQueue_->addPeriodicTask2(task_);
108	  }
109	  else if (task_ && task_->finished()) {
110	    A2_LOG_DEBUG("task finished detected");
111	    lastGetPeerTime_ = global::wallclock();
112	    if (numRetry_ < MAX_RETRIES &&
113	        (btRuntime_->getMaxPeers() == 0 ||
114	         btRuntime_->getMaxPeers() >
115	             static_cast<int>(peerStorage_->countAllPeer()))) {
116	      ++numRetry_;
117	      A2_LOG_DEBUG(fmt("Too few peers. peers=%lu, max_peers=%d."
118	                       " Try again(%d)",
119	                       static_cast<unsigned long>(peerStorage_->countAllPeer()),
120	                       btRuntime_->getMaxPeers(), numRetry_));
121	    }
122	    else {
123	      numRetry_ = 0;
124	    }
125	    task_.reset();
126	  }
127	
128	  e_->addCommand(std::unique_ptr<Command>(this));
129	  return false;
130	}
