60	bool DHTPeerAnnounceStorage::InfoHashLess::operator()(
61	    const std::shared_ptr<DHTPeerAnnounceEntry>& lhs,
62	    const std::shared_ptr<DHTPeerAnnounceEntry>& rhs) const
63	{
64	  return memcmp(lhs->getInfoHash(), rhs->getInfoHash(), DHT_ID_LENGTH) < 0;
65	}
