67	std::shared_ptr<DHTPeerAnnounceEntry>
68	DHTPeerAnnounceStorage::getPeerAnnounceEntry(const unsigned char* infoHash)
69	{
70	  auto entry = std::make_shared<DHTPeerAnnounceEntry>(infoHash);
71	
72	  auto i = entries_.lower_bound(entry);
73	
74	  if (i != entries_.end() &&
75	      memcmp(infoHash, (*i)->getInfoHash(), DHT_ID_LENGTH) == 0) {
76	    entry = *i;
77	  }
78	  else {
79	    entries_.insert(i, entry);
80	  }
81	  return entry;
82	}
