94	bool DHTPeerAnnounceStorage::contains(const unsigned char* infoHash) const
95	{
96	  auto entry = std::make_shared<DHTPeerAnnounceEntry>(infoHash);
97	  return std::binary_search(entries_.begin(), entries_.end(), entry,
98	                            InfoHashLess());
99	}
