112	void DHTPeerAnnounceStorage::handleTimeout()
113	{
114	  A2_LOG_DEBUG(fmt("Now purge peer announces(%lu entries) which are timed out.",
115	                   static_cast<unsigned long>(entries_.size())));
116	  std::for_each(std::begin(entries_), std::end(entries_),
117	                [](const std::shared_ptr<DHTPeerAnnounceEntry>& e) {
118	                  e->removeStalePeerAddrEntry(DHT_PEER_ANNOUNCE_PURGE_INTERVAL);
119	                });
120	
121	  for (auto i = std::begin(entries_); i != std::end(entries_);) {
122	    if ((*i)->empty()) {
123	      entries_.erase(i++);
124	    }
125	    else {
126	      ++i;
127	    }
128	  }
129	  A2_LOG_DEBUG(fmt("Currently %lu peer announce entries",
130	                   static_cast<unsigned long>(entries_.size())));
131	}
