133	void DHTPeerAnnounceStorage::announcePeer()
134	{
135	  A2_LOG_DEBUG("Now announcing peer.");
136	  for (auto& e : entries_) {
137	    if (e->getLastUpdated().difference(global::wallclock()) <
138	        DHT_PEER_ANNOUNCE_INTERVAL) {
139	      continue;
140	    }
141	    e->notifyUpdate();
142	    auto task = taskFactory_->createPeerAnnounceTask(e->getInfoHash());
143	    taskQueue_->addPeriodicTask2(task);
144	    A2_LOG_DEBUG(fmt("Added 1 peer announce: infoHash=%s",
145	                     util::toHex(e->getInfoHash(), DHT_ID_LENGTH).c_str()));
146	  }
147	}
