63	std::string DHTTokenTracker::generateToken(const unsigned char* infoHash,
64	                                           const std::string& ipaddr,
65	                                           uint16_t port,
66	                                           const unsigned char* secret) const
67	{
68	  unsigned char src[DHT_ID_LENGTH + COMPACT_LEN_IPV6 + SECRET_SIZE];
69	  memset(src, 0, sizeof(src));
70	  int compactlen = bittorrent::packcompact(src + DHT_ID_LENGTH, ipaddr, port);
71	  if (compactlen == 0) {
72	    throw DL_ABORT_EX(fmt("Token generation failed: ipaddr=%s, port=%u",
73	                          ipaddr.c_str(), port));
74	  }
75	  memcpy(src, infoHash, DHT_ID_LENGTH);
76	  memcpy(src + DHT_ID_LENGTH + COMPACT_LEN_IPV6, secret, SECRET_SIZE);
77	  unsigned char md[20];
78	  message_digest::digest(md, sizeof(md), MessageDigest::sha1().get(), src,
79	                         sizeof(src));
80	  return std::string(&md[0], &md[sizeof(md)]);
81	}
82	
83	std::string DHTTokenTracker::generateToken(const unsigned char* infoHash,
84	                                           const std::string& ipaddr,
85	                                           uint16_t port) const
86	{
87	  return generateToken(infoHash, ipaddr, port, secret_[0]);
88	}
