90	bool DHTTokenTracker::validateToken(const std::string& token,
91	                                    const unsigned char* infoHash,
92	                                    const std::string& ipaddr,
93	                                    uint16_t port) const
94	{
95	  for (auto& elem : secret_) {
96	    if (generateToken(infoHash, ipaddr, port, elem) == token) {
97	      return true;
98	    }
99	  }
100	  return false;
101	}
