    A2_LOG_ERROR_EX(EX_EXCEPTION_CAUGHT, e);
  }
}

void DHTPeerAnnounceCommand::setPeerAnnounceStorage(
    DHTPeerAnnounceStorage* storage)
{
  peerAnnounceStorage_ = storage;
}

